  1074  static void*
  1075  alloc_post_buffer(struct coro *coro, size_t size, bool allow_file)
  1076  {
  1077      struct file_backed_buffer *buf;
  1078      void *ptr = (void *)MAP_FAILED;
  1079      int fd;
  1080
  1081      if (LIKELY(size < 1<<20)) {
  1082          ptr = coro_malloc(coro, size);
  1083
  1084          if (LIKELY(ptr))
  1085              return ptr;
  1086      }
  1087
  1088      if (UNLIKELY(!allow_file))
  1089          return NULL;
  1090
  1091      fd = create_temp_file();
  1092      if (UNLIKELY(fd < 0))
  1093          return NULL;
  1094
  1095      if (UNLIKELY(ftruncate(fd, (off_t)size) < 0)) {
  1096          close(fd);
  1097          return NULL;
  1098      }
  1099
  1100      if (MAP_HUGETLB) {
  1101          ptr = mmap(NULL, size, PROT_READ | PROT_WRITE,
  1102                     MAP_PRIVATE | MAP_HUGETLB, fd, 0);
  1103      }
  1104      if (UNLIKELY(ptr == MAP_FAILED))
  1105          ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
  1106      close(fd);
  1107      if (UNLIKELY(ptr == MAP_FAILED))
  1108          return NULL;
  1109
  1110      buf = coro_malloc_full(coro, sizeof(*buf), free_post_buffer);
  1111      if (UNLIKELY(!buf)) {
  1112          munmap(ptr, size);
  1113          return NULL;
  1114      }
  1115
  1116      buf->ptr = ptr;
  1117      buf->size = size;
  1118      return ptr;
  1119  }
